      SUBROUTINE FRAME2CC     CALCULATES CONTRIBUTION OF SECOND-ORDER MATRIX TO THE C     BILINEAR TERMS IN A MISALIGNMENTCC     LIST OF COMMON BLOCKSC      INCLUDE 'ELM8H.CIN'      INCLUDE 'ELM8J.CIN'      INCLUDE 'TS.CIN'CC----------------------------------------------------------------      DO 50 J = 1, 5      IND = 0      DO 50 K2 = 1, 6      DO 50 K1 = 1, K2      IND = IND + 1      DO 40 M = 1, 6      GT(J,K1,M) = GT(J,K1,M) - TS(J,IND)*CT0(K2,M)      GT(J,K2,M) = GT(J,K2,M) - TS(J,IND)*CT0(K1,M)   40 CONTINUE   50 CONTINUEC      RETURN      END